'use strict';
const workspaceRole=window.PORTAL_ROLE||'client';
demo.adjustments??=[];
if(!localStorage.getItem('ecocharge-demo-v1')){demo.client={name:'Lox',email:'lox@example.com',status:'Active',note:''};demo.balance=0;demo.portfolio=[];}
const isActivePlan=()=>demo.plan?.status==='active';
const availableForPlan=()=>Math.round((demo.balance+(isActivePlan()?demo.plan.capital:0)-pendingWithdrawals())*100)/100;
const draftFundingGap=()=>Math.max(0,Math.round(((demo.planDraft?.capital||250)-availableForPlan())*100)/100);
const currentPortalBase=new URL('./',document.baseURI);
$('.role-switch')?.remove();
$('.prototype-bar>span').innerHTML='<i></i> INTERACTIVE DEMO <span class="prototype-explain">· Sample finances · browser-only accounts</span>';
$('.prototype-bar').insertAdjacentHTML('beforeend',`<a href="./" class="portal-home-link">${icon('out')} Project overview</a>`);
$('.account-actions').insertAdjacentHTML('beforeend','<button class="icon-btn portal-signout" data-action="signout" aria-label="Sign out" title="Sign out">'+icon('out')+'</button>');
// Shared EcoCharge branding is rendered in the page template.
$('.balance-card .card-heading').firstChild.textContent='AVAILABLE DEMO BALANCE ';
$('.balance-card [data-action="topup"]').innerHTML=icon('plus')+' Add demo funds';
$('.balance-card [data-action="withdraw"]').innerHTML=icon('download')+' Request withdrawal';
$('.metrics-grid .metric-card:nth-last-child(2)>span').textContent='Assigned stations';
document.title='EcoCharge — '+(workspaceRole==='admin'?'Team workspace':'Client account');
actions.signout=()=>{sessionStorage.removeItem('ecocharge-entry:'+(workspaceRole==='admin'?'staff':'client'));location.assign(currentPortalBase)};
const setRoleBeforePortal=setRole;
setRole=function(next){if(next!==workspaceRole){location.assign(new URL(next==='admin'?'team/':'login/',currentPortalBase));return}setRoleBeforePortal(next)};
actions['view-client']=()=>location.assign(new URL('client/?preview=1',currentPortalBase));
actions['guide-manager']=()=>location.assign(new URL('team/',currentPortalBase));
actions['contact-show-staff']=actions['guide-manager'];
actions['open-staff']=actions['guide-manager'];
actions['demo-guide']=()=>openModal(`<h2>Your EcoCharge demo</h2><ol class="engine-explanation"><li><strong>Choose a weekly plan.</strong><span>Select an amount and reference stations.</span></li><li><strong>Request demo funding.</strong><span>The manager can approve the request in the separate team account. No money is collected.</span></li><li><strong>Activate your allocation.</strong><span>Available demo funds move to invested demo capital. Your manager can record a sample weekly credit.</span></li></ol><button class="button primary" data-action="engine-details">Understand the revenue model</button>`);

// Each portal keeps its own URL/history. No client-side role switch is presented as authorization.
let routeInitialized=false,restoringRoute=false;
renderNav=function(){const tabs=role==='admin'?[['overview','grid','Overview'],['clients','users','Client'],['stations','map','Stations'],['requests','chat','Inbox'],['tariffs','zap','Rates']]:[['dashboard','grid','Overview'],['map','map','Stations'],['assets','assets','My plan'],['documents','file','Documents'],['tariffs','zap','Plans']];const active=role==='admin'?(adminTab==='plan'?'clients':adminTab):tab;$('.main-nav').innerHTML=tabs.map(([id,i,label])=>`<button class="nav-item ${active===id?'active':''}" data-tab="${id}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('');const url=new URL(location);url.searchParams.delete('view');url.searchParams.delete('preview');url.searchParams.set('tab',role==='admin'?adminTab:tab);if(!restoringRoute&&url.href!==location.href){if(routeInitialized)history.pushState({},'',url);else history.replaceState({},'',url)}routeInitialized=true;const skip=$('#skip-content');if(skip)skip.href=role==='admin'?'#admin-view':'#client-view';renderContactSurfaces()};
window.addEventListener('popstate',()=>{restoringRoute=true;const requested=new URL(location).searchParams.get('tab');if(workspaceRole==='admin'){adminTab=['overview','clients','stations','requests','tariffs','plan'].includes(requested)?requested:'overview';renderAdmin()}else{tab=['dashboard','map','assets','documents','tariffs'].includes(requested)?requested:'dashboard';renderClientTab()}restoringRoute=false});

const contactBeforePortal=renderContactSurfaces;
renderContactSurfaces=function(){contactBeforePortal();const welcome=$('#client-next-step');if(!welcome)return;const p=demo.plan,d=demo.planDraft,unread=unreadReplies();let title='Make your first allocation clear.',copy='Choose your weekly plan, review reference stations and request demo funding.',action='tariffs',cta='Choose a weekly plan';if(d){title=draftFundingGap()>0?'Your plan is saved.':'Your demo funds are ready.';copy=draftFundingGap()>0?`${d.name} · ${money(d.capital)}. Request ${money(draftFundingGap())} in demo funds to continue.`:`Activate ${money(d.capital)} in the ${d.name} plan and follow its weekly calculation.`;action=draftFundingGap()>0?'request-plan-funding':'activate-draft';cta=draftFundingGap()>0?'Request demo funding':'Activate my demo plan'}else if(isActivePlan()){title='Your participation, at a glance.';copy=`${p.stationIds.length} reference stations · ${p.rate.toFixed(1)}% per week on ${money(p.capital)} of demo capital.`;action='sessions';cta='View weekly allocations'}if(unread){title='Your manager has replied.';copy='Read the answer and continue from your saved plan.';action='conversations';cta='Read '+unread+' '+(unread===1?'reply':'replies')}welcome.innerHTML=`<div class="next-step-copy"><span class="contact-eyebrow">CLIENT ACCOUNT · ${escapeHtml(demo.client.name)}</span><h2>${title}</h2><p>${copy}</p></div><div class="next-step-actions"><button class="button primary" data-action="${action}">${cta} ${icon('arrow')}</button><button class="button secondary" data-action="manager">${icon('chat')} Ask my manager</button></div><ol class="account-progress" aria-label="Account setup"><li class="${p||d?'complete':'current'}"><span>1</span>Choose a plan</li><li class="${isActivePlan()?'complete':d?'current':''}"><span>2</span>Demo funding</li><li class="${isActivePlan()?'current':''}"><span>3</span>Weekly allocation</li></ol>`;const launcher=$('#manager-launcher');if(launcher){launcher.classList.add('portal-contact');launcher.hidden=true;}renderRevenueModel()};
function renderRevenueModel(){let el=$('#revenue-model');if(!el){el=document.createElement('section');el.id='revenue-model';el.className='panel revenue-model';$('.metrics-grid').after(el)}el.hidden=role!=='client'||tab!=='dashboard';el.innerHTML=`<div class="section-heading"><div><span class="eyebrow">HOW YOUR PARTICIPATION WORKS</span><h2>Charging activity supports the model.</h2></div><button class="text-button" data-action="engine-details">View the calculation ${icon('arrow')}</button></div><div class="revenue-path"><div>${icon('zap')}<strong>Drivers charge</strong><small>Payments generate operating revenue</small></div><span>→</span><div><b>43%</b><strong>Company participation</strong><small>Proposed network ownership assumption</small></div><span>→</span><div>${icon('calendar')}<strong>Your weekly allocation</strong><small>Invested capital × your plan rate</small></div></div><p class="model-caption">Demo model. Ownership and operating revenue are not connected. No additional payment is credited for each car.</p>`;}

function planTerms(){const t=demo.tariffs.find(t=>t.id===chosenTier);return{tierId:t.id,name:t.name,rate:t.rate,period:'week',capital:investmentDraft,stationIds:chosenStations.slice(),appliedAt:new Date().toISOString()}}
function activateAllocation(p){if(!validDemoInvestment(p.capital)||availableForPlan()<p.capital)return false;const previous=isActivePlan()?demo.plan.capital:0;demo.balance=Math.round((demo.balance+previous-p.capital)*100)/100;demo.plan={...p,status:'active'};demo.portfolio=p.stationIds.slice();delete demo.planDraft;activity('Activated '+p.name+' demo plan: '+money(p.capital)+' at '+p.rate+'% per week');persist();renderMap();return true}
actions['apply-plan']=()=>{const tier=demo.tariffs.find(t=>t.id===chosenTier);updateTariffMath();if(!Number.isFinite(investmentDraft)||investmentDraft<MIN_DEMO_INVESTMENT||investmentDraft>1e7||Math.abs(investmentDraft*100-Math.round(investmentDraft*100))>.00001){$('#tariff-error').textContent='Enter an amount from $250, with at most two decimal places.';return}if(chosenStations.length!==tier.count){$('#tariff-error').textContent='Select '+tier.count+' reference stations.';return}const gap=Math.max(0,investmentDraft-availableForPlan());openModal(`<h2>Review your weekly plan</h2><ul class="modal-list"><li><strong>${escapeHtml(tier.name)} · ${tier.count} stations</strong><small>Reference selection</small></li><li><strong>Demo investment</strong><small>${money(investmentDraft)}</small></li><li><strong>Weekly plan rate</strong><small>${tier.rate.toFixed(1)}%</small></li><li><strong>Weekly illustration</strong><small>${money(weeklyCredit(investmentDraft,tier.rate))}</small></li></ul><div class="modal-note">${gap>0?'Save this plan, then request '+money(gap)+' in demo funding.':'Activating this plan moves available demo funds into invested capital.'} No real payment is collected.</div><button class="button primary" data-action="confirm-plan">${gap>0?'Save plan & continue':'Activate demo allocation'}</button>`)};
actions['confirm-plan']=()=>{if(!validDemoInvestment(investmentDraft)){toast('Choose a demo amount of at least $250.');return}const p=planTerms();if(activateAllocation(p)){$('#modal').close();if(role==='admin')renderAdmin();else renderClientTab();toast('Demo allocation activated.')}else{demo.planDraft=p;persist();openModal(`<h2>Your plan is saved</h2><p>${escapeHtml(p.name)} · ${money(p.capital)} · ${p.rate.toFixed(1)}% per week.</p><div class="modal-note">Request ${money(draftFundingGap())} in sample funds. Your manager reviews the request in the team workspace.</div><button class="button primary" data-action="request-plan-funding">Request demo funding</button><button class="button secondary" data-action="back-overview">Return to overview</button>`)}};
actions['activate-draft']=()=>{if(!demo.planDraft)return;if(!validDemoInvestment(demo.planDraft.capital)){toast('Update this draft to at least $250 in Plans.');return}if(!activateAllocation(demo.planDraft)){toast('The plan needs additional demo funding.');return}renderClientTab();toast('Your weekly demo plan is active.')};
actions['back-overview']=()=>{$('#modal').close();tab='dashboard';renderClientTab()};
paymentModal=function(type){const topup=type==='topup';openModal(`<h2>${topup?'Add demo funds':'Request a withdrawal'}</h2><p>${topup?'Submit a sample funding request for your manager to review.':'Request a transfer from your available demo balance.'}</p><form id="payment-form" data-type="${type}"><label for="payment-amount">Amount (USD)</label><input id="payment-amount" type="number" inputmode="decimal" min="1" max="100000" step=".01" value="${topup?250:Math.min(250,Math.max(0,demo.balance-pendingWithdrawals()))}" required>${topup?'<div class="quick-amounts"><button type="button" data-amount="500">$500</button><button type="button" data-amount="250">$250</button><button type="button" data-amount="300">$300</button></div>':''}<div class="modal-note">Demo request only. No bank or card is charged. Available balance: ${money(demo.balance-pendingWithdrawals())}.</div><div id="payment-error" class="form-error" role="alert"></div><button type="submit" class="button primary">Send demo request</button></form>`)};
actions['request-plan-funding']=()=>{paymentModal('topup');$('#payment-amount').value=draftFundingGap()||250};
document.addEventListener('submit',e=>{if(e.target.id!=='payment-form')return;e.preventDefault();e.stopImmediatePropagation();const amount=Number($('#payment-amount').value),type=e.target.dataset.type;if(!Number.isFinite(amount)||amount<1||amount>100000||Math.abs(amount*100-Math.round(amount*100))>.00001||(type==='withdraw'&&amount>demo.balance-pendingWithdrawals())){$('#payment-error').textContent='Enter a valid amount within the available balance, with at most two decimals.';return}demo.requests.push({id:'REQ-'+Date.now().toString(36).toUpperCase(),type,amount,status:'Pending',date:new Date().toISOString()});activity('Client requested demo '+type+': '+money(amount));persist();openModal(`<div class="success-icon">✓</div><h2>Request saved</h2><p>${money(amount)} · awaiting your manager’s review.</p><p class="modal-note">This request is stored in this browser. Your account updates when the manager reviews it.</p><button class="button primary" data-action="history">View request status</button><button class="button secondary" data-action="back-overview">Back to overview</button>`);},true);

managerClientRecord=function(){const p=demo.plan;return `<section class="panel client-record"><div class="client-record-top"><span class="avatar">LX</span><div class="client-record-name"><h2>${escapeHtml(demo.client.name)}</h2><span>Client login: lox · CL-1001</span></div><span class="pill">Demo account</span></div><dl class="client-record-summary"><div><dt>Available balance</dt><dd>${money(demo.balance)}</dd></div><div><dt>Invested capital</dt><dd>${money(p?.capital||0)}<small>${p?p.rate+'% per week':'No active plan'}</small></dd></div><div><dt>Assigned stations</dt><dd>${demo.portfolio.length}<small>${p?escapeHtml(p.name):'No plan selected'}</small></dd></div></dl><div class="client-record-actions"><button class="button primary" data-action="manage-account">Edit client account ${icon('arrow')}</button><button class="button secondary" data-action="simulate-session">Record a demo week</button><button class="button secondary" data-action="view-client">Preview client</button><button class="button secondary" data-action="account-audit">Change history</button></div><p class="form-hint">Edit balance, invested capital, assigned station count and weekly tariff. Changes appear in the client workspace in this browser.</p></section>`};
actions['manage-account']=()=>{if(role!=='admin')return;const p=demo.plan;openModal(`<h2>Manage client account</h2><p>Client: ${escapeHtml(demo.client.name)} · login lox</p><form id="account-control-form"><div class="account-edit-grid"><div><label for="control-balance">Available demo balance (USD)</label><input id="control-balance" type="number" min="0" max="10000000" step=".01" value="${demo.balance}" required></div><div><label for="control-capital">Invested demo capital (USD)</label><input id="control-capital" type="number" min="0" max="10000000" step=".01" value="${p?.capital||0}" required></div><div><label for="control-tier">Weekly tariff</label><select id="control-tier">${demo.tariffs.map(t=>`<option value="${t.id}" ${t.id===(p?.tierId||'single')?'selected':''}>${t.name} · ${t.rate}% / week</option>`).join('')}</select></div><div><label for="control-stations">Assigned charging stations</label><input id="control-stations" type="number" min="0" max="50" step="1" value="${demo.portfolio.length}" required></div></div><div class="control-preview" id="control-preview"></div><p class="form-hint">Changing the tariff suggests its station count. You can adjust the count separately for this demo; the rate follows the tariff.</p><label for="control-note">Reason for change (optional)</label><input id="control-note" maxlength="180" placeholder="Demo account setup"><div id="control-error" class="form-error" role="alert"></div><button class="button primary" type="submit">Save client account</button><p class="form-hint">These are direct demo adjustments, not deposits or real transactions. Previous weekly credits keep their original terms.</p></form>`);updateControlPreview()};
function updateControlPreview(){if(!$('#control-capital'))return;const t=demo.tariffs.find(t=>t.id===$('#control-tier').value),capital=Number($('#control-capital').value);$('#control-preview').textContent=Number.isFinite(capital)&&capital>=0?money(capital)+' × '+t.rate+'% = '+money(weeklyCredit(capital,t.rate))+' per demo week':'Enter a valid invested amount.'}
document.addEventListener('input',e=>{if(e.target.id==='control-capital')updateControlPreview()});
document.addEventListener('change',e=>{if(e.target.id==='control-tier'){$('#control-stations').value=demo.tariffs.find(t=>t.id===e.target.value).count;updateControlPreview()}});
document.addEventListener('submit',e=>{if(e.target.id!=='account-control-form')return;e.preventDefault();if(role!=='admin')return;const balance=Number($('#control-balance').value),capital=Number($('#control-capital').value),count=Number($('#control-stations').value),tier=demo.tariffs.find(t=>t.id===$('#control-tier').value),reason=$('#control-note').value.trim()||'Demo account adjustment';const moneyValid=n=>Number.isFinite(n)&&n>=0&&n<=1e7&&Math.abs(n*100-Math.round(n*100))<.00001;if(capital>0&&!validDemoInvestment(capital)){$('#control-error').textContent='An active demo investment must be at least $250. Use zero to clear it.';return}if(!moneyValid(balance)||!moneyValid(capital)||!Number.isInteger(count)||count<0||count>50||capital>0&&count===0||balance<pendingWithdrawals()){$('#control-error').textContent='Use valid amounts, keep reserved withdrawals covered, and assign at least one station for an active investment.';return}if(count>stations.length){$('#control-error').textContent='Wait for the station directory to load.';return}const before={balance:demo.balance,capital:demo.plan?.capital||0,stations:demo.portfolio.length,tariff:demo.plan?.name||'None'};const ids=[...new Set([...demo.portfolio,...stations.map(s=>s.id)])].filter(id=>stations.some(s=>s.id===id)).slice(0,count);demo.balance=balance;demo.portfolio=ids;demo.plan=capital>0?{tierId:tier.id,name:tier.name,rate:tier.rate,period:'week',capital,stationIds:ids.slice(),status:'active',appliedAt:new Date().toISOString()}:null;delete demo.planDraft;demo.adjustments.unshift({actor:'admin',date:new Date().toISOString(),reason,before,after:{balance,capital,stations:count,tariff:capital>0?tier.name:'None'}});activity('Manager updated client: '+money(balance)+' available, '+money(capital)+' invested, '+count+' stations, '+tier.name+' · '+reason);persist();$('#modal').close();renderAdmin();toast('Client account updated.')});
actions['account-audit']=()=>openModal(`<h2>Client account change history</h2>${demo.adjustments.length?demo.adjustments.slice(0,30).map(a=>`<article class="account-change"><strong>${escapeHtml(a.reason)}</strong><small>${escapeHtml(a.date)} · ${escapeHtml(a.actor)}</small><p>Available: ${money(a.before.balance)} → ${money(a.after.balance)}<br>Invested: ${money(a.before.capital)} → ${money(a.after.capital)}<br>Stations: ${a.before.stations} → ${a.after.stations}<br>Tariff: ${escapeHtml(a.before.tariff)} → ${escapeHtml(a.after.tariff)}</p></article>`).join(''):'<p>No direct account changes yet.</p>'}`);
const adminBeforePortal=renderAdmin;
renderAdmin=function(){adminBeforePortal();$('#profile-name').textContent=demo.manager.name;$('#profile-role').textContent='ADMIN · DEMO';if(adminTab==='clients'){$('#admin-view .manager-layout>div').innerHTML=managerClientRecord()+managerPlanSummary();}if(adminTab==='overview'){$('.manager-heading p').textContent='Manage the client account, review funding and record weekly demo allocations.'}renderRevenueModel()};
const clientBeforePortal=renderClientTab;
renderClientTab=function(){clientBeforePortal();renderRevenueModel();if(tab==='assets'&&!demo.portfolio.length)$('#asset-list').innerHTML='<div class="empty-state">No stations assigned yet. Choose a weekly plan to build your demo allocation.</div>';};
const tariffsBeforePortal=renderTariffs;
renderTariffs=function(){tariffsBeforePortal();const historyButton=$('#tariffs-section .session-panel [data-action="simulate-session"]');if(historyButton&&role==='client'){historyButton.dataset.action='sessions';historyButton.textContent='View history'}};
actions.profile=()=>openModal(`<h2>${role==='admin'?'Team account':'Client account'}</h2><ul class="modal-list"><li><strong>Username</strong><small>${role==='admin'?'admin':'lox'}</small></li><li><strong>Name</strong><small>${escapeHtml(role==='admin'?demo.manager.name:demo.client.name)}</small></li><li><strong>Workspace</strong><small>${role==='admin'?'Team operations':'Client participation'}</small></li></ul><button class="button secondary" data-action="signout">Sign out</button>`);
actions.yield=actions.sessions;
// Synchronize separate client/team tabs on this device without claiming cross-device delivery.
window.addEventListener('storage',e=>{if(e.key!=='ecocharge-demo-v1'||!e.newValue)return;try{const latest=JSON.parse(e.newValue);if(!Number.isFinite(latest.balance)||!Array.isArray(latest.portfolio))return;demo=latest;ensureClient();ensureManager();ensureTariffs();demo.adjustments??=[];renderNumbers();if(role==='admin')renderAdmin();else renderClientTab();refreshManager();toast('Account updated from another demo workspace.')}catch{}});
// Profile changes and money requests remain local. No automatic client-to-staff navigation.
const historyBeforePortal=actions.history;
actions.history=()=>{historyBeforePortal();$('#modal-content>p').textContent='Available sample balance: '+money(demo.balance)+' · Reserved: '+money(pendingWithdrawals());};
actions['confirm-reset']=()=>{if(role!=='admin'){toast('Ask the demo manager to reset the workspace.');return}demo={balance:0,portfolio:[],plan:null,sessions:[],adjustments:[],requests:[],tickets:[],activity:[],tariffs:defaultTiers(),tariffModelVersion:2,weeklyModelVersion:1,companyShare:43,client:{name:'Lox',email:'lox@example.com',status:'Active',note:''},manager:managerDefaults()};chosenTier='single';chosenStations=stations.length?[stations[0].id]:[];investmentDraft=250;contactDraft=null;inboxFilter='all';filter='all';$('#state-filter').value='';$('#station-search').value='';$('#modal').close();persist();renderMap();renderAdmin();refreshManager();toast('Demo account reset. No real account was affected.')};
if(workspaceRole==='client')document.querySelector('footer [data-action="reset"]')?.remove();

// Carry an explored public example into an unfunded account without changing an existing plan.
const initBeforePublicExample=init;
init=async function(){
 await initBeforePublicExample();
 if(workspaceRole!=='client'||!stations.length)return;
 try{
  const raw=sessionStorage.getItem('ecocharge-explore');
  if(!raw)return;
  const intent=JSON.parse(raw),tier=demo.tariffs.find(t=>t.id===intent.tierId);
  sessionStorage.removeItem('ecocharge-explore');
  if(!tier)return;
  const capital=validDemoInvestment(intent.capital)?intent.capital:MIN_DEMO_INVESTMENT;
  if(demo.plan||demo.planDraft){toast('Your existing demo plan has been kept. You can compare a new plan in Plans.');return;}
  chosenTier=tier.id;investmentDraft=capital;chosenStations=[];normalizeSelection(tier);
  tab='tariffs';renderClientTab();
 }catch{}
};
